<?php $active_menu='finance';include 'header.php';require_once __DIR__.'/../foundation.php';oecrm_require_permission($conn,'gst','view');$companyId=oecrm_current_company_id($conn);$year=(int)($_GET['year']??date('Y'));$rows=mysqli_query($conn,"SELECT m.month_no,COALESCE(i.collected,0) collected,COALESCE(e.paid,0) paid FROM (SELECT 1 month_no UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12)m LEFT JOIN(SELECT MONTH(invoice_date) month_no,SUM(tax_amount) collected FROM finance_invoices WHERE company_id=$companyId AND YEAR(invoice_date)=$year AND status<>'cancelled' GROUP BY MONTH(invoice_date))i USING(month_no) LEFT JOIN(SELECT MONTH(expense_date) month_no,SUM(tax_amount) paid FROM finance_expenses WHERE company_id=$companyId AND YEAR(expense_date)=$year GROUP BY MONTH(expense_date))e USING(month_no)");?><div id="page-wrapper" class="compact-admin-page"><div class="foundation-titlebar"><a href="finance.php"><i class="fa fa-arrow-left"></i> Finance</a><h2>GST Report <?php echo $year;?></h2></div><div class="panel panel-default"><div class="panel-body table-responsive"><table class="table foundation-table"><thead><tr><th>Month</th><th>GST Collected</th><th>GST Paid</th><th>GST Payable</th></tr></thead><tbody><?php $tc=$tp=0;while($r=mysqli_fetch_assoc($rows)):$tc+=$r['collected'];$tp+=$r['paid'];?><tr><td><?php echo date('F',mktime(0,0,0,$r['month_no'],1));?></td><td><?php echo number_format($r['collected'],2);?></td><td><?php echo number_format($r['paid'],2);?></td><td><?php echo number_format($r['collected']-$r['paid'],2);?></td></tr><?php endwhile;?><tr><th>Annual Total</th><th><?php echo number_format($tc,2);?></th><th><?php echo number_format($tp,2);?></th><th><?php echo number_format($tc-$tp,2);?></th></tr></tbody></table></div></div></div><?php include 'footer.php';?>
